INSERT INTO dictation_progress (learner, direction, level, source, current_word_id, answered, hinted, asked_ids, asked_count, right_count, round_start, subject_id) VALUES (:learner, :direction, :level, :source, 0, 1, 0, '', 0, 0, (SELECT COALESCE(MAX(id), 0) FROM dictation_attempt WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER)), CAST(:subject_id AS INTEGER)) ON CONFLICT(learner, subject_id) DO UPDATE SET direction = excluded.direction, level = excluded.level, source = excluded.source WHERE dictation_progress.current_word_id = 0 OR dictation_progress.answered = 1
